preConditionHook:
// Brooks's trending dojis: every one of the last runBars bars has a body no
// bigger than dojiFraction of its own range, yet the bars still step up --
// each close above the prior close and neither the high nor the low below the
// prior bar's. The one place in this bucket where dojis read WITH the trend
// rather than as a weak-signal filter, which is why it is kept whole: the
// conjunction 'doji on every bar of the run' cannot be ANDed in from DojiBar,
// which only ever sees bar 0.
//
// All-of-N in the StrongTrendBarRun shape: start true, let a failing bar clear
// the flag, loop unconditionally so EasyLanguage's lack of short-circuiting
// cannot matter. Both flags are class members and are reset at the top.
//
// The doji test is a product, not a quotient, so a zero-range bar cannot raise
// EL's runtime divide-by-zero; on such a bar the absolute body is 0 and the
// test passes, which is the intended reading of a one-price bar. std::fabs
// stands in for EL's AbsValue (ACCEPTED: pure scalar arithmetic).
//
// Highs and lows are compared INCLUSIVELY and the closes STRICTLY, exactly as
// the source states it. Deepest bar read is runBars.
dojiUp = true;
dojiDown = true;
for (kk = 0; kk < (int)runBars; ++kk) {
    if (el_gt(std::fabs(close[kk] - open[kk]), dojiFraction * (high[kk] - low[kk]))) {
        dojiUp = false;
        dojiDown = false;
    }
    if (el_le(close[kk], close[kk + 1])) dojiUp = false;
    if (el_lt(high[kk], high[kk + 1])) dojiUp = false;
    if (el_lt(low[kk], low[kk + 1])) dojiUp = false;
    if (el_ge(close[kk], close[kk + 1])) dojiDown = false;
    if (el_gt(high[kk], high[kk + 1])) dojiDown = false;
    if (el_gt(low[kk], low[kk + 1])) dojiDown = false;
}
